      "content": "CREATE TABLE \"app_release\" (\n    \"id\" TEXT NOT NULL,\n    \"platform\" TEXT NOT NULL,\n    \"version\" TEXT NOT NULL,\n    \"build\" INTEGER NOT NULL,\n    \"minimumVersion\" TEXT NOT NULL,\n    \"minimumBuild\" INTEGER NOT NULL,\n    \"status\" TEXT NOT NULL DEFAULT 'draft',\n    \"storeUrl\" TEXT,\n    \"title\" TEXT,\n    \"message\" TEXT,\n    \"notes\" TEXT,\n    \"publishedAt\" TIMESTAMPTZ(3),\n    \"createdAt\" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    \"updatedAt\" TIMESTAMPTZ(3) NOT NULL,\n\n    CONSTRAINT \"app_release_pkey\" PRIMARY KEY (\"id\"),\n    CONSTRAINT \"app_release_platform_check\" CHECK (\"platform\" IN ('ios', 'android')),\n    CONSTRAINT \"app_release_status_check\" CHECK (\"status\" IN ('draft', 'published', 'withdrawn')),\n    CONSTRAINT \"app_release_build_check\" CHECK (\"minimumBuild\" >= 0 AND \"build\" >= \"minimumBuild\"),\n    CONSTRAINT \"app_release_published_check\" CHECK (\"status\" <> 'published' OR \"publishedAt\" IS NOT NULL)\n);\n\nCREATE UNIQUE INDEX \"app_release_platform_build_key\" ON \"app_release\"(\"platform\", \"build\");\n-- Una sola release publicada gobierna cada plataforma; los borradores no la reemplazan.\nCREATE UNIQUE INDEX \"app_release_published_platform_key\" ON \"app_release\"(\"platform\")\n  WHERE \"status\" = 'published';\n\n-- El init otorga DML por defecto: esta tabla solo admite lecturas de la aplicacion.\nREVOKE INSERT, UPDATE, DELETE ON TABLE \"app_release\" FROM taomangalam_app;\nGRANT SELECT ON TABLE \"app_release\" TO taomangalam_app, taomangalam_readonly;"
    },
    {
      "sourceRef": "server/prisma/migrations/20260927223537_init/migration.sql:7-14",
      "description": "Los privilegios por defecto del migrador conceden SELECT/INSERT/UPDATE/DELETE a app y SELECT a readonly. La migración de app_release restringe la escritura heredada por app."
    },
    {
      "sourceRef": "server/src/models/app-release.ts:5-14",
      "description": "El consumidor real readPublishedRelease ejecuta exclusivamente SELECT sobre app_release."
